#!/usr/bin/env bash
set -euo pipefail
# All media here is generated by the disposable emulator, before any signing material is loaded.
if ! gradle --no-daemon -p android :app:connectedDebugAndroidTest '-Pandroid.testInstrumentationRunnerArguments.class=gr.myworkstation.chat.VideoActivityTest#emulatorCaptureProducesPlayableMp4InRamWithoutLocalVideo'; then
  adb logcat -b main -b system -d -v brief -s MediaRecorder:V MediaRecorderJNI:V MediaRecorderClient:V StagefrightRecorder:V MPEG4Writer:V ACodec:V CCodec:V Codec2Client:V AudioRecord:V AudioSource:V Camera3-Device:V FuseAppLoop:V AppFuseBridge:V || true
  exit 1
fi
# Preserve the complete suite after the focused probe, including real capture again.
gradle --no-daemon -p android :app:connectedDebugAndroidTest

# Synthetic UI proof only, produced by ConversationAppearanceTest in the disposable emulator.
mkdir -p android/app/build/reports/androidTests/ui-proof
adb pull /sdcard/Android/data/gr.myworkstation.chat.preview/files/ui-proof/. android/app/build/reports/androidTests/ui-proof/
